{
  "id": "ch6-comprehensive-design",
  "title": "第6章 综合设计：从问题到结构的选择与实现",
  "subtitle": "数据结构线性部分与半线性部分的综合决策",
  "language": "zh-CN",
  "audience": "计算机专业本科低年级学生",
  "theme": "slate",
  "tutor": {
    "suggestions": [
      "为什么栈和队列仍被归为线性结构，而不是与线性表并列？",
      "顺序存储的随机访问是 O(1)，但插入删除为什么是 O(n)？能否举一个具体例子？",
      "递归与非递归在时间和空间上到底差在哪里？",
      "面对一个实际问题，应该先从 ADT 入手，还是先从存储结构入手？"
    ],
    "kb": [
      {
        "pattern": "逻辑结构|logical structure",
        "answer": "数据元素之间的逻辑关系，如集合、线性、树形、图状，独立于计算机的存储方式。"
      },
      {
        "pattern": "ADT|抽象数据类型",
        "answer": "Abstract Data Type，由数据对象、数据关系及一组操作定义，只说明‘做什么’，不涉及‘怎么做’。"
      },
      {
        "pattern": "线性结构|linear structure",
        "answer": "元素之间为一对一的前驱-后继关系，包括线性表、栈、队列、串等。"
      },
      {
        "pattern": "半线性结构|semi-linear structure",
        "answer": "元素之间为一对多的层次关系，典型代表是树；每个结点可有多个孩子，但只有一个双亲（根除外）。"
      },
      {
        "pattern": "顺序存储|sequential storage",
        "answer": "用一段地址连续的存储单元依次存放数据元素，支持随机访问，但插入删除可能需搬移元素。"
      },
      {
        "pattern": "链式存储|linked storage",
        "answer": "用指针把离散存储的结点链接起来，插入删除无需搬移，但访问需顺序遍历，并额外消耗指针空间。"
      }
    ]
  },
  "scenes": [
    {
      "id": "6-1-design-flow",
      "kind": "content",
      "eyebrow": "6.1",
      "headline": "从问题到结构：一条可复用的设计主线",
      "lead": "数据结构设计的起点不是代码，而是对问题关系的准确刻画。",
      "notes": "以浏览器撤销（Undo）为例：操作序列并不是‘先发生先撤销’，而是最近操作先回退，这揭示出 LIFO 关系，从而指向栈而非队列。强调每一步的产出物：问题抽象得到数据对象与关系，逻辑结构选择决定 ADT 接口，存储实现才涉及数组或指针。",
      "blocks": [
        {
          "id": "b6-1-flow",
          "type": "flow",
          "intent": "设计流程的五步：问题抽象 → 逻辑结构选择 → ADT 定义 → 存储实现 → 算法设计，并标注每步的关键产出",
          "size": "l"
        },
        {
          "id": "b6-1-callout",
          "type": "callout",
          "intent": "用浏览器撤销、任务调度、文件目录三个真实场景说明同一步流程如何导出不同结构",
          "size": "s"
        }
      ]
    },
    {
      "id": "6-2-linear-vs-semilinear",
      "kind": "content",
      "eyebrow": "6.2",
      "headline": "线性 vs 半线性：关系特征决定结构",
      "lead": "元素之间是一对一还是一对多，直接决定应选用线性表、栈、队列还是树形结构。",
      "notes": "线性结构的关系是‘前驱-后继’唯一，半线性结构允许一个元素拥有多个后继。要提醒学生：栈和队列不是新的关系类型，而是线性表在操作限制上的特化；树的一对多关系则天然适合表达层级、分类和递归分解。",
      "blocks": [
        {
          "id": "b6-2-compare",
          "type": "compare",
          "intent": "左侧列线性结构（数组、链表、栈、队列）的关系特征与典型操作，右侧列半线性结构（树、二叉树）的关系特征与典型操作",
          "size": "l"
        },
        {
          "id": "b6-2-callout",
          "type": "callout",
          "intent": "辨析误区：把‘栈/队列’当成与线性表并列的独立结构，忽视它们只是受限的线性表",
          "size": "s"
        }
      ]
    },
    {
      "id": "6-3-storage-decision",
      "kind": "content",
      "eyebrow": "6.3",
      "headline": "顺序存储还是链式存储：决策树与权衡",
      "lead": "存储结构的选择要在随机访问、插入删除、空间连续性与扩展性之间做取舍。",
      "notes": "给出可量化的判断标准：若主要操作是按下标访问且长度变化小，顺序存储的 O(1) 随机访问更优；若频繁头插/头删或长度不可预估，链式存储避免搬移。用决策树把‘是否频繁插入删除’‘是否需要随机访问’‘数据规模是否可知’三个问题串起来。",
      "blocks": [
        {
          "id": "b6-3-diagram",
          "type": "diagram",
          "intent": "顺序/链式存储选择决策树：从‘数据规模是否确定’‘是否频繁插入删除’‘是否需要随机访问’三个问题分支到推荐存储结构",
          "size": "l"
        },
        {
          "id": "b6-3-table",
          "type": "table",
          "intent": "顺序表与链表在随机访问、插入删除、空间开销、缓存友好性上的具体对比",
          "size": "m"
        }
      ]
    },
    {
      "id": "6-4-recursion-iteration",
      "kind": "content",
      "eyebrow": "6.4",
      "headline": "递归与非递归：实现范式的取舍",
      "lead": "递归以栈空间换代码简洁，非递归则以可读性换取对内存与执行过程的可控。",
      "notes": "用同一棵二叉树的前序遍历作对照：递归版隐式使用系统栈，代码短但深度大时有栈溢出风险；非递归版显式维护栈，可控制内存并便于中断/恢复。指出常见误区：认为递归一定更慢——实际时间复杂度相同，差异在常数因子和栈空间。",
      "blocks": [
        {
          "id": "b6-4-compare",
