          "size": "l"
        },
        {
          "id": "b6-4-callout",
          "type": "callout",
          "intent": "常见误区：递归比非递归慢；忽视递归深度限制导致的栈溢出",
          "size": "s"
        }
      ]
    },
    {
      "id": "6-5-quiz",
      "kind": "quiz",
      "headline": "随堂检验：同一问题的三种结构视角",
      "notes": "通过表达式求值、任务调度、文件目录三个场景，检验学生能否从问题关系出发选择结构，而不是死记‘栈用于表达式’。鼓励说明理由，关注关系特征与操作约束。",
